223	     * Builds the customer code assigned to a newly created owner, formatted as
224	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
225	     * already registered in the same city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
226	     *
227	     * @param owner the owner being created
228	     * @return the customer code for the owner
229	     */
230	    private String customerCode(Owner owner) {
231	        String city = owner.getCity();
232	        long existingInCity = this.clinicService.findAllOwners().stream()
233	            .filter(existing -> Objects.equals(existing.getCity(), city))
234	            .count();
235	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
236	    }
