238	    private boolean isDuplicateOwner(Owner owner) {
239	        return this.clinicService.findAllOwners().stream()
240	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
241	    }
242	
243	    /**
244	     * Determines whether the given owner's email address is already used by another owner. An owner
245	     * without an email address never conflicts. The comparison is case-insensitive and ignores
246	     * surrounding or repeated whitespace, so e.g. {@code "  John.Smith@Example.com "} and
247	     * {@code "john.smith@example.com"} are treated as the same address.
248	     *
249	     * @param owner the candidate owner to check
250	     * @return {@code true} if another owner already uses the email address, {@code false} otherwise
251	     */
252	    private boolean isDuplicateEmail(Owner owner) {
253	        String email = normalize(owner.getEmail());
254	        if (email == null || email.isEmpty()) {
255	            return false;
256	        }
257	        return this.clinicService.findAllOwners().stream()
258	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
259	    }
260	
261	    /**
262	     * Normalises a value for case- and whitespace-insensitive duplicate detection: surrounding
263	     * whitespace is stripped, any run of internal whitespace is collapsed to a single space and all
264	     * letters are lower-cased. This is what makes {@code "  john   smith "} and {@code "John Smith"}
265	     * count as the same person (or, for e-mail, the same address) when detecting duplicates.
266	     *
267	     * @param value the raw value, may be {@code null}
268	     * @return the normalised value, or {@code null} if {@code value} was {@code null}
269	     */
270	    private static String normalize(String value) {
271	        if (value == null) {
272	            return null;
273	        }
274	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
275	    }
